import React, { useMemo, useState } from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  Box,
  Drawer,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  IconButton,
  Card,
  CardContent,
  CardMedia,
  Button,
  Chip,
  TextField,
  InputAdornment,
  Grid,
  Divider,
  Badge,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Avatar,
  Menu,
  MenuItem,
  Snackbar,
  Alert,
  Paper,
} from "@mui/material";

import {
  Menu as MenuIcon,
  Home as HomeIcon,
  RestaurantMenu as RestaurantMenuIcon,
  ShoppingCart as ShoppingCartIcon,
  ReceiptLong as OrdersIcon,
  Person as PersonIcon,
  Logout as LogoutIcon,
  Search as SearchIcon,
  Add as AddIcon,
  Remove as RemoveIcon,
  Delete as DeleteIcon,
  Close as CloseIcon,
  Star as StarIcon,
  AccessTime as TimeIcon,
} from "@mui/icons-material";

/* -------------------------------------------------------
   SAMPLE MENU DATA
   Later this will come from MongoDB.
------------------------------------------------------- */

const menuItems = [
  {
    id: 1,
    name: "Masala Dosa",
    category: "Breakfast",
    price: 80,
    rating: 4.5,
    preparationTime: 10,
    description: "Crispy dosa served with potato masala, chutney and sambar.",
    image:
      "https://images.unsplash.com/photo-1668236543090-82eba5ee5976?w=800",
  },
  {
    id: 2,
    name: "Idli Sambar",
    category: "Breakfast",
    price: 60,
    rating: 4.4,
    preparationTime: 8,
    description: "Soft steamed idlis served with hot sambar and chutney.",
    image:
      "https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=800",
  },
  {
    id: 3,
    name: "Veg Biryani",
    category: "Lunch",
    price: 140,
    rating: 4.6,
    preparationTime: 20,
    description: "Aromatic basmati rice cooked with vegetables and spices.",
    image:
      "https://images.unsplash.com/photo-1589302168068-964664d93dc0?w=800",
  },
  {
    id: 4,
    name: "Chicken Biryani",
    category: "Lunch",
    price: 180,
    rating: 4.8,
    preparationTime: 25,
    description: "Flavorful chicken biryani prepared with traditional spices.",
    image:
      "https://images.unsplash.com/photo-1563379091339-03246963d96c?w=800",
  },
  {
    id: 5,
    name: "Paneer Tikka",
    category: "Snacks",
    price: 120,
    rating: 4.5,
    preparationTime: 15,
    description: "Grilled paneer cubes marinated with Indian spices.",
    image:
      "https://images.unsplash.com/photo-1567188040759-fb8a883dc6d8?w=800",
  },
  {
    id: 6,
    name: "Samosa",
    category: "Snacks",
    price: 30,
    rating: 4.3,
    preparationTime: 8,
    description: "Crispy samosa filled with spicy potato mixture.",
    image:
      "https://images.unsplash.com/photo-1601050690597-df0568f70950?w=800",
  },
  {
    id: 7,
    name: "Veg Sandwich",
    category: "Snacks",
    price: 70,
    rating: 4.2,
    preparationTime: 10,
    description: "Fresh vegetables and cheese served in toasted bread.",
    image:
      "https://images.unsplash.com/photo-1528735602780-2552fd46c7af?w=800",
  },
  {
    id: 8,
    name: "Masala Chai",
    category: "Beverages",
    price: 25,
    rating: 4.6,
    preparationTime: 5,
    description: "Hot Indian tea prepared with milk and aromatic spices.",
    image:
      "https://images.unsplash.com/photo-1594631252845-29fc4cc8cde9?w=800",
  },
  {
    id: 9,
    name: "Cold Coffee",
    category: "Beverages",
    price: 60,
    rating: 4.4,
    preparationTime: 5,
    description: "Chilled creamy coffee served with ice.",
    image:
      "https://images.unsplash.com/photo-1461023058943-07fcbe16d735?w=800",
  },
];

const categories = [
  "All",
  "Breakfast",
  "Lunch",
  "Snacks",
  "Beverages",
];

const drawerWidth = 240;

const UserDashboard = ({ user, onLogout }) => {
  const [mobileOpen, setMobileOpen] = useState(false);

  const [activePage, setActivePage] = useState("Home");

  const [search, setSearch] = useState("");

  const [selectedCategory, setSelectedCategory] = useState("All");

  const [cart, setCart] = useState([]);

  const [orders, setOrders] = useState([]);

  const [profileAnchor, setProfileAnchor] = useState(null);

  const [cartOpen, setCartOpen] = useState(false);

  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  /* -------------------------------------------------------
     FILTER MENU
  ------------------------------------------------------- */

  const filteredMenu = useMemo(() => {
    return menuItems.filter((item) => {
      const matchesCategory =
        selectedCategory === "All" ||
        item.category === selectedCategory;

      const matchesSearch = item.name
        .toLowerCase()
        .includes(search.toLowerCase());

      return matchesCategory && matchesSearch;
    });
  }, [search, selectedCategory]);

  /* -------------------------------------------------------
     CART FUNCTIONS
  ------------------------------------------------------- */

  const addToCart = (item) => {
    setCart((currentCart) => {
      const existingItem = currentCart.find(
        (cartItem) => cartItem.id === item.id
      );

      if (existingItem) {
        return currentCart.map((cartItem) =>
          cartItem.id === item.id
            ? {
              ...cartItem,
              quantity: cartItem.quantity + 1,
            }
            : cartItem
        );
      }

      return [
        ...currentCart,
        {
          ...item,
          quantity: 1,
        },
      ];
    });

    showMessage(`${item.name} added to cart`);
  };

  const increaseQuantity = (id) => {
    setCart((currentCart) =>
      currentCart.map((item) =>
        item.id === id
          ? {
            ...item,
            quantity: item.quantity + 1,
          }
          : item
      )
    );
  };

  const decreaseQuantity = (id) => {
    setCart((currentCart) =>
      currentCart
        .map((item) =>
          item.id === id
            ? {
              ...item,
              quantity: item.quantity - 1,
            }
            : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const removeFromCart = (id) => {
    setCart((currentCart) =>
      currentCart.filter((item) => item.id !== id)
    );
  };

  const cartCount = cart.reduce(
    (total, item) => total + item.quantity,
    0
  );

  const cartTotal = cart.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );

  /* -------------------------------------------------------
     PLACE ORDER
  ------------------------------------------------------- */

  const placeOrder = () => {
    if (cart.length === 0) {
      showMessage("Your cart is empty", "warning");
      return;
    }

    const newOrder = {
      id: `ORD-${Date.now().toString().slice(-6)}`,
      items: [...cart],
      total: cartTotal,
      status: "Placed",
      createdAt: new Date().toLocaleString(),
    };

    setOrders((currentOrders) => [
      newOrder,
      ...currentOrders,
    ]);

    setCart([]);

    setCartOpen(false);

    setActivePage("My Orders");

    showMessage("Order placed successfully");
  };

  /* -------------------------------------------------------
     SNACKBAR
  ------------------------------------------------------- */

  const showMessage = (
    message,
    severity = "success"
  ) => {
    setSnackbar({
      open: true,
      message,
      severity,
    });
  };

  const closeSnackbar = () => {
    setSnackbar({
      ...snackbar,
      open: false,
    });
  };

  /* -------------------------------------------------------
     LOGOUT
  ------------------------------------------------------- */

  const handleLogout = () => {
    setProfileAnchor(null);

    if (onLogout) {
      onLogout();
    }
  };

  /* -------------------------------------------------------
     NAVIGATION
  ------------------------------------------------------- */

  const handleNavigation = (page) => {
    setActivePage(page);
    setMobileOpen(false);
  };

  /* -------------------------------------------------------
     DRAWER
  ------------------------------------------------------- */

  const drawerContent = (
    <Box sx={{ height: "100%" }}>
      <Box
        sx={{
          height: 70,
          display: "flex",
          alignItems: "center",
          px: 2.5,
          background:
            "linear-gradient(135deg, #2e7d32, #43a047)",
          color: "white",
        }}
      >
        <RestaurantMenuIcon sx={{ mr: 1 }} />

        <Typography
          variant="h6"
          sx={{ fontWeight: 800 }}
        >
          CanteenPro
        </Typography>
      </Box>

      <List sx={{ px: 1.5, pt: 2 }}>
        <ListItemButton
          selected={activePage === "Home"}
          onClick={() => handleNavigation("Home")}
          sx={{
            borderRadius: 2,
            mb: 0.5,
          }}
        >
          <ListItemIcon>
            <HomeIcon />
          </ListItemIcon>

          <ListItemText primary="Home" />
        </ListItemButton>

        <ListItemButton
          selected={activePage === "Menu"}
          onClick={() => handleNavigation("Menu")}
          sx={{
            borderRadius: 2,
            mb: 0.5,
          }}
        >
          <ListItemIcon>
            <RestaurantMenuIcon />
          </ListItemIcon>

          <ListItemText primary="Menu" />
        </ListItemButton>

        <ListItemButton
          selected={activePage === "My Orders"}
          onClick={() => handleNavigation("My Orders")}
          sx={{
            borderRadius: 2,
            mb: 0.5,
          }}
        >
          <ListItemIcon>
            <OrdersIcon />
          </ListItemIcon>

          <ListItemText primary="My Orders" />
        </ListItemButton>

        <ListItemButton
          selected={activePage === "Profile"}
          onClick={() => handleNavigation("Profile")}
          sx={{
            borderRadius: 2,
            mb: 0.5,
          }}
        >
          <ListItemIcon>
            <PersonIcon />
          </ListItemIcon>

          <ListItemText primary="Profile" />
        </ListItemButton>

        <Divider sx={{ my: 2 }} />

        <ListItemButton
          onClick={handleLogout}
          sx={{
            borderRadius: 2,
          }}
        >
          <ListItemIcon>
            <LogoutIcon />
          </ListItemIcon>

          <ListItemText primary="Logout" />
        </ListItemButton>
      </List>
    </Box>
  );

  /* -------------------------------------------------------
     FOOD CARD
  ------------------------------------------------------- */

  const FoodCard = ({ item }) => (
    <Card
      sx={{
        height: "100%",
        borderRadius: 3,
        overflow: "hidden",
        transition: "0.25s",
        border: "1px solid #eeeeee",

        "&:hover": {
          transform: "translateY(-5px)",
          boxShadow: 6,
        },
      }}
    >
      <CardMedia
        component="img"
        height="190"
        image={item.image}
        alt={item.name}
        sx={{
          objectFit: "cover",
        }}
      />

      <CardContent>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-start",
          }}
        >
          <Typography
            variant="h6"
            sx={{
              fontWeight: 700,
            }}
          >
            {item.name}
          </Typography>

          <Chip
            label={item.category}
            size="small"
            sx={{
              backgroundColor: "#e8f5e9",
              color: "#2e7d32",
              fontWeight: 600,
            }}
          />
        </Box>

        <Typography
          variant="body2"
          color="text.secondary"
          sx={{
            mt: 1,
            minHeight: 42,
          }}
        >
          {item.description}
        </Typography>

        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 1,
            mt: 1.5,
          }}
        >
          <StarIcon
            sx={{
              fontSize: 18,
              color: "#f5b400",
            }}
          />

          <Typography
            variant="body2"
            sx={{ fontWeight: 600 }}
          >
            {item.rating}
          </Typography>

          <TimeIcon
            sx={{
              fontSize: 18,
              ml: 1,
              color: "#777",
            }}
          />

          <Typography
            variant="body2"
            color="text.secondary"
          >
            {item.preparationTime} min
          </Typography>
        </Box>

        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            mt: 2,
          }}
        >
          <Typography
            variant="h6"
            sx={{
              fontWeight: 800,
              color: "#2e7d32",
            }}
          >
            ₹{item.price}
          </Typography>

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => addToCart(item)}
            sx={{
              borderRadius: 2,
              backgroundColor: "#2e7d32",

              "&:hover": {
                backgroundColor: "#1b5e20",
              },
            }}
          >
            Add
          </Button>
        </Box>
      </CardContent>
    </Card>
  );

  /* -------------------------------------------------------
     HOME PAGE
  ------------------------------------------------------- */

  const renderHome = () => (
    <Box>
      <Paper
        elevation={0}
        sx={{
          p: {
            xs: 3,
            md: 5,
          },
          borderRadius: 4,
          background:
            "linear-gradient(135deg, #e8f5e9, #f1f8e9)",
          mb: 4,
        }}
      >
        <Typography
          variant="h4"
          sx={{
            fontWeight: 800,
            color: "#1b5e20",
            mb: 1,
          }}
        >
          Welcome, {user?.name || "User"}
        </Typography>

        <Typography
          variant="body1"
          color="text.secondary"
        >
          Order your favorite food quickly and easily.
        </Typography>

        <Button
          variant="contained"
          onClick={() => handleNavigation("Menu")}
          sx={{
            mt: 3,
            backgroundColor: "#2e7d32",
            borderRadius: 2,
          }}
        >
          Explore Menu
        </Button>
      </Paper>

      <Typography
        variant="h5"
        sx={{
          fontWeight: 800,
          mb: 2,
        }}
      >
        Popular Food
      </Typography>

      <Grid container spacing={3}>
        {menuItems.slice(0, 4).map((item) => (
          <Grid
            item
            xs={12}
            sm={6}
            md={3}
            key={item.id}
          >
            <FoodCard item={item} />
          </Grid>
        ))}
      </Grid>
    </Box>
  );

  /* -------------------------------------------------------
     MENU PAGE
  ------------------------------------------------------- */

  const renderMenu = () => (
    <Box>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          mb: 3,
          color: "#1b5e20",
        }}
      >
        Menu
      </Typography>

      <TextField
        fullWidth
        placeholder="Search food..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        sx={{
          mb: 3,
          backgroundColor: "white",
        }}
        InputProps={{
          startAdornment: (
            <InputAdornment position="start">
              <SearchIcon />
            </InputAdornment>
          ),
        }}
      />

      <Box
        sx={{
          display: "flex",
          gap: 1,
          flexWrap: "wrap",
          mb: 4,
        }}
      >
        {categories.map((category) => (
          <Button
            key={category}
            variant={
              selectedCategory === category
                ? "contained"
                : "outlined"
            }
            onClick={() =>
              setSelectedCategory(category)
            }
            sx={{
              borderRadius: 5,

              ...(selectedCategory === category
                ? {
                  backgroundColor: "#2e7d32",
                  "&:hover": {
                    backgroundColor: "#1b5e20",
                  },
                }
                : {
                  color: "#2e7d32",
                  borderColor: "#2e7d32",
                }),
            }}
          >
            {category}
          </Button>
        ))}
      </Box>

      {filteredMenu.length === 0 ? (
        <Paper
          sx={{
            p: 5,
            textAlign: "center",
            borderRadius: 3,
          }}
        >
          <Typography variant="h6">
            No food items found
          </Typography>

          <Typography
            color="text.secondary"
            sx={{ mt: 1 }}
          >
            Try another search or category.
          </Typography>
        </Paper>
      ) : (
        <Grid container spacing={3}>
          {filteredMenu.map((item) => (
            <Grid
              item
              xs={12}
              sm={6}
              md={4}
              key={item.id}
            >
              <FoodCard item={item} />
            </Grid>
          ))}
        </Grid>
      )}
    </Box>
  );

  /* -------------------------------------------------------
     ORDERS PAGE
  ------------------------------------------------------- */

  const renderOrders = () => (
    <Box>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#1b5e20",
          mb: 3,
        }}
      >
        My Orders
      </Typography>

      {orders.length === 0 ? (
        <Paper
          sx={{
            p: 5,
            textAlign: "center",
            borderRadius: 3,
          }}
        >
          <OrdersIcon
            sx={{
              fontSize: 60,
              color: "#81c784",
            }}
          />

          <Typography
            variant="h6"
            sx={{ mt: 2 }}
          >
            No orders yet
          </Typography>

          <Typography
            color="text.secondary"
            sx={{ mt: 1 }}
          >
            Place your first order from the menu.
          </Typography>

          <Button
            variant="contained"
            onClick={() => handleNavigation("Menu")}
            sx={{
              mt: 3,
              backgroundColor: "#2e7d32",
            }}
          >
            Browse Menu
          </Button>
        </Paper>
      ) : (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            gap: 2,
          }}
        >
          {orders.map((order) => (
            <Card
              key={order.id}
              sx={{
                borderRadius: 3,
              }}
            >
              <CardContent>
                <Box
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: {
                      xs: "flex-start",
                      sm: "center",
                    },
                    flexDirection: {
                      xs: "column",
                      sm: "row",
                    },
                    gap: 1,
                  }}
                >
                  <Box>
                    <Typography
                      variant="h6"
                      sx={{ fontWeight: 800 }}
                    >
                      {order.id}
                    </Typography>

                    <Typography
                      variant="body2"
                      color="text.secondary"
                    >
                      {order.createdAt}
                    </Typography>
                  </Box>

                  <Chip
                    label={order.status}
                    color="success"
                    sx={{
                      fontWeight: 700,
                    }}
                  />
                </Box>

                <Divider sx={{ my: 2 }} />

                {order.items.map((item) => (
                  <Box
                    key={item.id}
                    sx={{
                      display: "flex",
                      justifyContent: "space-between",
                      py: 0.5,
                    }}
                  >
                    <Typography>
                      {item.name} × {item.quantity}
                    </Typography>

                    <Typography
                      sx={{ fontWeight: 600 }}
                    >
                      ₹{item.price * item.quantity}
                    </Typography>
                  </Box>
                ))}

                <Divider sx={{ my: 2 }} />

                <Box
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                  }}
                >
                  <Typography
                    sx={{ fontWeight: 800 }}
                  >
                    Total
                  </Typography>

                  <Typography
                    sx={{
                      fontWeight: 800,
                      color: "#2e7d32",
                    }}
                  >
                    ₹{order.total}
                  </Typography>
                </Box>
              </CardContent>
            </Card>
          ))}
        </Box>
      )}
    </Box>
  );

  /* -------------------------------------------------------
     PROFILE PAGE
  ------------------------------------------------------- */

  const renderProfile = () => (
    <Box>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#1b5e20",
          mb: 3,
        }}
      >
        My Profile
      </Typography>

      <Card
        sx={{
          maxWidth: 650,
          borderRadius: 4,
        }}
      >
        <CardContent sx={{ p: 4 }}>
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: 2,
              mb: 4,
            }}
          >
            <Avatar
              sx={{
                width: 70,
                height: 70,
                backgroundColor: "#2e7d32",
                fontSize: 30,
              }}
            >
              {(user?.name || "U")
                .charAt(0)
                .toUpperCase()}
            </Avatar>

            <Box>
              <Typography
                variant="h5"
                sx={{ fontWeight: 800 }}
              >
                {user?.name || "User"}
              </Typography>

              <Chip
                label="USER"
                size="small"
                sx={{
                  mt: 0.5,
                  backgroundColor: "#e8f5e9",
                  color: "#2e7d32",
                  fontWeight: 700,
                }}
              />
            </Box>
          </Box>

          <Typography
            variant="body2"
            color="text.secondary"
          >
            Mobile Number
          </Typography>

          <Typography
            variant="body1"
            sx={{
              fontWeight: 600,
              mb: 3,
            }}
          >
            {user?.mobile || "Not available"}
          </Typography>

          <Typography
            variant="body2"
            color="text.secondary"
          >
            Account Type
          </Typography>

          <Typography
            variant="body1"
            sx={{
              fontWeight: 600,
            }}
          >
            User
          </Typography>
        </CardContent>
      </Card>
    </Box>
  );

  /* -------------------------------------------------------
     CURRENT PAGE
  ------------------------------------------------------- */

  const renderPage = () => {
    if (activePage === "Menu") {
      return renderMenu();
    }

    if (activePage === "My Orders") {
      return renderOrders();
    }

    if (activePage === "Profile") {
      return renderProfile();
    }

    return renderHome();
  };

  /* -------------------------------------------------------
     MAIN UI
  ------------------------------------------------------- */

  return (
    <Box
      sx={{
        display: "flex",
        minHeight: "100vh",
        backgroundColor: "#f5f7f6",
      }}
    >
      {/* DESKTOP DRAWER */}

      <Box
        component="nav"
        sx={{
          width: {
            md: drawerWidth,
          },
          flexShrink: {
            md: 0,
          },
        }}
      >
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={() => setMobileOpen(false)}
          ModalProps={{
            keepMounted: true,
          }}
          sx={{
            display: {
              xs: "block",
              md: "none",
            },

            "& .MuiDrawer-paper": {
              width: drawerWidth,
              boxSizing: "border-box",
            },
          }}
        >
          {drawerContent}
        </Drawer>

        <Drawer
          variant="permanent"
          sx={{
            display: {
              xs: "none",
              md: "block",
            },

            "& .MuiDrawer-paper": {
              width: drawerWidth,
              boxSizing: "border-box",
              borderRight: "1px solid #e0e0e0",
            },
          }}
          open
        >
          {drawerContent}
        </Drawer>
      </Box>

      {/* MAIN CONTENT */}

      <Box
        component="main"
        sx={{
          flexGrow: 1,
          minWidth: 0,
        }}
      >
        {/* TOP BAR */}

        <AppBar
          position="sticky"
          elevation={0}
          sx={{
            backgroundColor: "white",
            color: "#1b1b1b",
            borderBottom: "1px solid #e0e0e0",
          }}
        >
          <Toolbar>
            <IconButton
              edge="start"
              onClick={() => setMobileOpen(true)}
              sx={{
                display: {
                  md: "none",
                },
                mr: 1,
              }}
            >
              <MenuIcon />
            </IconButton>

            <Typography
              variant="h6"
              sx={{
                flexGrow: 1,
                fontWeight: 800,
                color: "#2e7d32",
              }}
            >
              {activePage}
            </Typography>

            <IconButton
              onClick={() => setCartOpen(true)}
              sx={{ mr: 1 }}
            >
              <Badge
                badgeContent={cartCount}
                color="error"
              >
                <ShoppingCartIcon />
              </Badge>
            </IconButton>

            <IconButton
              onClick={(event) =>
                setProfileAnchor(event.currentTarget)
              }
            >
              <Avatar
                sx={{
                  width: 40,
                  height: 40,
                  backgroundColor: "#2e7d32",
                }}
              >
                {(user?.name || "U")
                  .charAt(0)
                  .toUpperCase()}
              </Avatar>
            </IconButton>

            <Menu
              anchorEl={profileAnchor}
              open={Boolean(profileAnchor)}
              onClose={() => setProfileAnchor(null)}
            >
              <MenuItem
                onClick={() => {
                  setProfileAnchor(null);
                  handleNavigation("Profile");
                }}
              >
                <PersonIcon sx={{ mr: 1 }} />
                Profile
              </MenuItem>

              <MenuItem onClick={handleLogout}>
                <LogoutIcon sx={{ mr: 1 }} />
                Logout
              </MenuItem>
            </Menu>
          </Toolbar>
        </AppBar>

        {/* PAGE CONTENT */}

        <Box
          sx={{
            p: {
              xs: 2,
              sm: 3,
              md: 4,
            },
            maxWidth: 1500,
            mx: "auto",
          }}
        >
          {renderPage()}
        </Box>
      </Box>

      {/* CART DIALOG */}

      <Dialog
        open={cartOpen}
        onClose={() => setCartOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            fontWeight: 800,
          }}
        >
          Your Cart

          <IconButton
            onClick={() => setCartOpen(false)}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>

        <DialogContent dividers>
          {cart.length === 0 ? (
            <Box
              sx={{
                textAlign: "center",
                py: 5,
              }}
            >
              <ShoppingCartIcon
                sx={{
                  fontSize: 60,
                  color: "#bdbdbd",
                }}
              />

              <Typography
                variant="h6"
                sx={{ mt: 2 }}
              >
                Your cart is empty
              </Typography>

              <Typography
                color="text.secondary"
                sx={{ mt: 1 }}
              >
                Add some delicious food from the menu.
              </Typography>
            </Box>
          ) : (
            <>
              {cart.map((item) => (
                <Box
                  key={item.id}
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 2,
                    py: 2,
                  }}
                >
                  <Box
                    component="img"
                    src={item.image}
                    alt={item.name}
                    sx={{
                      width: 65,
                      height: 65,
                      objectFit: "cover",
                      borderRadius: 2,
                    }}
                  />

                  <Box
                    sx={{
                      flexGrow: 1,
                    }}
                  >
                    <Typography
                      sx={{
                        fontWeight: 700,
                      }}
                    >
                      {item.name}
                    </Typography>

                    <Typography
                      color="text.secondary"
                    >
                      ₹{item.price}
                    </Typography>

                    <Box
                      sx={{
                        display: "flex",
                        alignItems: "center",
                        mt: 1,
                      }}
                    >
                      <IconButton
                        size="small"
                        onClick={() =>
                          decreaseQuantity(item.id)
                        }
                      >
                        <RemoveIcon />
                      </IconButton>

                      <Typography
                        sx={{
                          minWidth: 25,
                          textAlign: "center",
                          fontWeight: 700,
                        }}
                      >
                        {item.quantity}
                      </Typography>

                      <IconButton
                        size="small"
                        onClick={() =>
                          increaseQuantity(item.id)
                        }
                      >
                        <AddIcon />
                      </IconButton>
                    </Box>
                  </Box>

                  <Box
                    sx={{
                      textAlign: "right",
                    }}
                  >
                    <Typography
                      sx={{
                        fontWeight: 700,
                      }}
                    >
                      ₹{item.price * item.quantity}
                    </Typography>

                    <IconButton
                      size="small"
                      color="error"
                      onClick={() =>
                        removeFromCart(item.id)
                      }
                    >
                      <DeleteIcon />
                    </IconButton>
                  </Box>
                </Box>
              ))}

              <Divider sx={{ my: 2 }} />

              <Box
                sx={{
                  display: "flex",
                  justifyContent: "space-between",
                }}
              >
                <Typography
                  variant="h6"
                  sx={{ fontWeight: 800 }}
                >
                  Total
                </Typography>

                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 800,
                    color: "#2e7d32",
                  }}
                >
                  ₹{cartTotal}
                </Typography>
              </Box>
            </>
          )}
        </DialogContent>

        <DialogActions sx={{ p: 2 }}>
          <Button
            onClick={() => setCartOpen(false)}
          >
            Continue Shopping
          </Button>

          <Button
            variant="contained"
            disabled={cart.length === 0}
            onClick={placeOrder}
            sx={{
              backgroundColor: "#2e7d32",

              "&:hover": {
                backgroundColor: "#1b5e20",
              },
            }}
          >
            Place Order
          </Button>
        </DialogActions>
      </Dialog>

      {/* MESSAGE */}

      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={closeSnackbar}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "center",
        }}
      >
        <Alert
          onClose={closeSnackbar}
          severity={snackbar.severity}
          variant="filled"
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default UserDashboard;
